def _regular_bytes(path: Path, *, max_bytes: int = 8_388_608) -> bytes:
    if ".." in path.parts:
        raise ValueError("traversal")
    if any(parent.is_symlink() for parent in (path, *path.parents)):
        raise ValueError("symlink")
    descriptor = os.open(path, os.O_RDONLY | os.O_NONBLOCK | os.O_NOFOLLOW)
    with os.fdopen(descriptor, "rb") as stream:
        info = os.fstat(stream.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_size > max_bytes:
            raise ValueError("regular-file/size")
        raw = stream.read(max_bytes + 1)
    if len(raw) > max_bytes:
        raise ValueError("file-size")
    return raw


def _leaves(raw: bytes):
    if len(raw) > FILE_CAP:
        raise ValueError("compressed-size")
    with gzip.GzipFile(fileobj=io.BytesIO(raw)) as stream:
        expanded = stream.read(EXPANDED_CAP + 1)
    if len(expanded) > EXPANDED_CAP:
        raise ValueError("expanded-size")
    document = strict_json(expanded.decode("utf-8"))
    if set(document) != {"format", "entries"} or document["format"] not in {"lossless-reviewed-leaves-v1", "lossless-reviewed-gzip-leaves-v1"}:
        raise ValueError("format")
    if not isinstance(document["entries"], list) or not document["entries"]:
        raise ValueError("entries")
    seen = set()
    for entry in document["entries"]:
        if document["format"] == "lossless-reviewed-leaves-v1":
            expected_fields = {"path", "sha256", "raw_base64"}
        else:
            expected_fields = {"path", "sha256", "gzip_utf8", "header_base64", "trailer_base64"}
        if set(entry) != expected_fields:
            raise ValueError("entry-shape")
        name = entry["path"]
        if not isinstance(name, str) or Path(name).name != name or name in {".", ".."}:
            raise ValueError("path")
        if not name.endswith(("-case-map.jsonl.gz", "-originals.json")) or name in seen:
            raise ValueError("leaf/duplicate")
        seen.add(name)
        if document["format"] == "lossless-reviewed-leaves-v1":
            payload = base64.b64decode(entry["raw_base64"], validate=True)
        else:
            if not isinstance(entry["gzip_utf8"], str):
                raise ValueError("gzip-text")
            content = entry["gzip_utf8"].encode("utf-8")
            if len(content) > FILE_CAP:
                raise ValueError("gzip-expanded-size")
            header = base64.b64decode(entry["header_base64"], validate=True)
            trailer = base64.b64decode(entry["trailer_base64"], validate=True)
            if len(header) != 10 or header[:4] != b"\x1f\x8b\x08\x00" or len(trailer) != 8:
                raise ValueError("gzip-envelope")
            payload = header + gzip.compress(content, compresslevel=9, mtime=0)[10:-8] + trailer
            if gzip.decompress(payload) != content:
                raise ValueError("gzip-recovery")
        if len(payload) > FILE_CAP or hashlib.sha256(payload).hexdigest() != entry["sha256"]:
            raise ValueError("raw-size/digest")
        yield name, payload


@contextmanager
def migration_view(migration: Path, *, expected_packs=None):
    """Expose every physical and packed leaf at its unchanged original basename."""
    # Do not resolve input before refusing symlinked ancestry.
    if ".." in migration.parts:
        raise ValueError("traversal")
    if any(parent.is_symlink() for parent in (migration, *migration.parents)):
        raise ValueError("symlink")
    pins = PACK_PINS if expected_packs is None else expected_packs
    present = {p.name for p in migration.glob("reviewed-leaves-*.json.gz")}
    if present != set(pins):
        raise ValueError("closed-pack-roster")
    with tempfile.TemporaryDirectory(prefix="gnd-reviewed-leaves-") as directory:
        root = Path(directory).resolve(strict=True)
        names = set()
        for path in sorted(migration.iterdir()):
            raw = _regular_bytes(path)
            if path.name.startswith("reviewed-leaves-") and path.name.endswith(".json.gz"):
                expected_sha, expected_count = pins[path.name]
                if hashlib.sha256(raw).hexdigest() != expected_sha:
                    raise ValueError("pack-pin")
                leaves = tuple(_leaves(raw))
                if expected_packs is None and {name: hashlib.sha256(payload).hexdigest() for name, payload in leaves} != {name: LEAF_PINS[name] for name in PACK_LEAVES[path.name]}:
                    raise ValueError("closed-leaf-roster")
                if len(leaves) != expected_count:
                    raise ValueError("leaf-roster-count")
            else:
                leaves = ((path.name, raw),)
            for name, payload in leaves:
                if name in names:
                    raise ValueError("physical/packed collision")
                names.add(name)
                (root / name).write_bytes(payload)
                (root / name).chmod(0o644)
        yield root
